// The only translation unit that includes the generated vnd_build_info.h. Keep
// it that way: a version bump regenerates that header, and if other TUs included
// it they would all recompile - which is exactly what phase 4 removed.
#include "core/dev/build_info.h"

#include "core/dev/vnd_build_info.h" // generated by build_id.py before the build

const char *vndVersion() { return VND_VERSION_STR; }

const char *vndBuildId() { return VND_BUILD_ID_STR; }

void vndBuildIdBytes(uint8_t out[8]) {
    const uint64_t h = VND_BUILD_ID_FNV;
    for (int i = 0; i < 8; i++) out[i] = (uint8_t)(h >> (8 * i));
}
